/* Service worker. It is generated by the server, and its version changes whenever the server restarts,
   so browsers always replace the old one. Pages and scripts are fetched fresh and only fall back to the
   saved copy when you are offline. */
const VERSION = 'oikres-__VERSION__';
const IMG_CACHE = 'oikres-img-v1';

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(VERSION).then((c) => c.add('/offline')).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    const old = keys.filter((k) => k !== VERSION && k !== IMG_CACHE);
    await Promise.all(old.map((k) => caches.delete(k)));
    await self.clients.claim();
    // An older version was running: refresh open tabs once so they stop showing stale files.
    if (old.length) (await self.clients.matchAll({ type: 'window' })).forEach((c) => { try { c.navigate(c.url); } catch (err) { /* tab closed */ } });
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);

  // Lodge photos on Cloudinary: cache first, keep the most recent 80.
  if (url.hostname === 'res.cloudinary.com' && req.destination === 'image') {
    e.respondWith(caches.open(IMG_CACHE).then(async (cache) => {
      const hit = await cache.match(req);
      if (hit) return hit;
      try {
        const res = await fetch(req);
        if (res.ok || res.type === 'opaque') { cache.put(req, res.clone()); cache.keys().then((k) => { if (k.length > 80) cache.delete(k[0]); }); }
        return res;
      } catch (err) { return Response.error(); }
    }));
    return;
  }
  if (url.origin !== location.origin) return;

  // Pages: always from the network; the offline page only when the network fails.
  if (req.mode === 'navigate') {
    e.respondWith(fetch(req).catch(() => caches.match('/offline')));
    return;
  }

  // Our own styles, scripts and icons: network first, saved copy only when offline.
  if (/^\/(css|js|icons)\//.test(url.pathname)) {
    e.respondWith((async () => {
      const cache = await caches.open(VERSION);
      try {
        const res = await fetch(req);
        if (res.ok) cache.put(req, res.clone());
        return res;
      } catch (err) {
        return (await cache.match(req)) || (await cache.match(req, { ignoreSearch: true })) || Response.error();
      }
    })());
  }
});
